#![allow(clippy::excessive_precision)]

use thermopack_rs::{Phase, SaftVrMie};

#[test]
fn test_saft_vrmie_pure_co2_states() {
    let eos = SaftVrMie::new(&["CO2"]).expect("failed to load CO2");
    assert_eq!(eos.num_components(), 1);

    // Point: T = 250.0 K, rho = 50.0 mol/m^3 (vapor)
    let prep = eos.prepare(250.0, &[1.0]).unwrap();
    let terms = prep.helmholtz_terms(50.0).unwrap();
    assert!(
        (terms.a_hs - 2.9279418014865172e-03).abs() < 1e-12,
        "a_hs diff: {}",
        (terms.a_hs - 2.9279418014865172e-03).abs()
    );
    assert!(
        (terms.a1 - -1.6329341430342525e+00).abs() < 1e-10,
        "a1 diff: {}",
        (terms.a1 - -1.6329341430342525e+00).abs()
    );
    assert!(
        (terms.a2 - -7.1498405669104528e+01).abs() < 1e-8,
        "a2 diff: {}",
        (terms.a2 - -7.1498405669104528e+01).abs()
    );
    assert!(
        (terms.a3 - -1.7426931006995510e+03).abs() < 1e-6,
        "a3 diff: {}",
        (terms.a3 - -1.7426931006995510e+03).abs()
    );
    let jet = prep.pressure_and_derivatives(50.0).unwrap();
    println!(
        "CO2 T=250 rho=50: d = {}, eta = {}, zeta_bar = {}, P_jet = {}, a_chain = {}, a_res = {}",
        prep.d()[0],
        prep.packing_fraction(50.0),
        prep.dispersion_packing_fraction(50.0),
        jet.pressure,
        terms.a_chain,
        terms.a_res
    );
    assert!(
        (jet.pressure - 1.0314379586043739e+05).abs() < 1.0314379586043739e+02,
        "P diff: {}",
        (jet.pressure - 1.0314379586043739e+05).abs()
    );
    let st = prep.state(50.0).unwrap();
    assert!(
        (st.ln_phi[0] - -7.5355607922518858e-03).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -7.5355607922518858e-03).abs()
    );

    // Point: T = 300.0 K, rho = 5000.0 mol/m^3 (subcritical dense gas)
    let prep = eos.prepare(300.0, &[1.0]).unwrap();
    let terms = prep.helmholtz_terms(5000.0).unwrap();
    assert!(
        (terms.a_hs - 3.1946016075735162e-01).abs() < 1e-12,
        "a_hs diff: {}",
        (terms.a_hs - 3.1946016075735162e-01).abs()
    );
    assert!(
        (terms.a1 - -1.7318039593034604e+02).abs() < 1e-10,
        "a1 diff: {}",
        (terms.a1 - -1.7318039593034604e+02).abs()
    );
    assert!(
        (terms.a2 - -4.5160020488158734e+03).abs() < 1e-8,
        "a2 diff: {}",
        (terms.a2 - -4.5160020488158734e+03).abs()
    );
    assert!(
        (terms.a3 - -3.0650382641946751e+05).abs() < 1e-6,
        "a3 diff: {}",
        (terms.a3 - -3.0650382641946751e+05).abs()
    );
    let jet = prep.pressure_and_derivatives(5000.0).unwrap();
    assert!(
        (jet.pressure - 6.5704472064612703e+06).abs() < 6.5704472064612701e+03,
        "P diff: {}",
        (jet.pressure - 6.5704472064612703e+06).abs()
    );
    let st = prep.state(5000.0).unwrap();
    assert!(
        (st.ln_phi[0] - -3.4878591645801371e-01).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -3.4878591645801371e-01).abs()
    );

    // Point: T = 350.0 K, rho = 15000.0 mol/m^3 (supercritical dense fluid)
    let prep = eos.prepare(350.0, &[1.0]).unwrap();
    let terms = prep.helmholtz_terms(15000.0).unwrap();
    assert!(
        (terms.a_hs - 1.1822473052941322e+00).abs() < 1e-12,
        "a_hs diff: {}",
        (terms.a_hs - 1.1822473052941322e+00).abs()
    );
    assert!(
        (terms.a1 - -5.6834745816045086e+02).abs() < 1e-10,
        "a1 diff: {}",
        (terms.a1 - -5.6834745816045086e+02).abs()
    );
    assert!(
        (terms.a2 - -6.0525779633463026e+03).abs() < 1e-8,
        "a2 diff: {}",
        (terms.a2 - -6.0525779633463026e+03).abs()
    );
    assert!(
        (terms.a3 - -2.5272483606788941e+05).abs() < 1e-6,
        "a3 diff: {}",
        (terms.a3 - -2.5272483606788941e+05).abs()
    );
    let jet = prep.pressure_and_derivatives(15000.0).unwrap();
    assert!(
        (jet.pressure - 2.3993221842738960e+07).abs() < 2.3993221842738960e+04,
        "P diff: {}",
        (jet.pressure - 2.3993221842738960e+07).abs()
    );
    let st = prep.state(15000.0).unwrap();
    assert!(
        (st.ln_phi[0] - -7.0353018711851778e-01).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -7.0353018711851778e-01).abs()
    );
}

#[test]
fn test_saft_vrmie_pure_co2_volume_and_saturation() {
    let eos = SaftVrMie::new(&["CO2"]).expect("failed to load CO2");
    let prep = eos.prepare(280.0, &[1.0]).unwrap();
    let p_target = 2.0e6; // 20 bar
    let vv = prep.volume(p_target, Phase::Vapor).unwrap();
    let jet_v = prep.pressure_and_derivatives(1.0 / vv).unwrap();
    assert!((jet_v.pressure - p_target).abs() < 1e-2);
    let vl = prep.volume(p_target, Phase::Liquid).unwrap();
    let jet_l = prep.pressure_and_derivatives(1.0 / vl).unwrap();
    assert!((jet_l.pressure - p_target).abs() < 1e-2);
    assert!(vl < vv);

    // Saturation pressure at 280 K: reference P_sat = 4.141998e+06 Pa
    let sat = prep.saturation_pressure(280.0).unwrap();
    assert!(
        (sat.pressure - 4.14199760e+06).abs() / 4.14199760e+06 < 1e-3,
        "sat P diff: {}",
        (sat.pressure - 4.14199760e+06).abs()
    );
    assert!((sat.liquid_volume - 4.85834503e-05).abs() / 4.85834503e-05 < 1e-2);
    assert!((sat.vapor_volume - 3.88138676e-04).abs() / 3.88138676e-04 < 1e-2);
}

#[test]
fn test_saft_vrmie_pure_c1_states() {
    let eos = SaftVrMie::new(&["C1"]).expect("failed to load C1");
    // T = 150.0 K, rho = 50.0 mol/m^3 (gas)
    let prep = eos.prepare(150.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(50.0).unwrap();
    assert!((jet.pressure - 6.1870819386312956e+04).abs() < 6.1870819386312959e+01);
    let st = prep.state(50.0).unwrap();
    assert!((st.ln_phi[0] - -7.7955310315769959e-03).abs() < 1e-5);

    // T = 200.0 K, rho = 2000.0 mol/m^3 (dense gas)
    let prep = eos.prepare(200.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(2000.0).unwrap();
    assert!((jet.pressure - 2.7334208412751378e+06).abs() < 2.7334208412751377e+03);
    let st = prep.state(2000.0).unwrap();
    assert!((st.ln_phi[0] - -1.6524678327966982e-01).abs() < 1e-5);

    // T = 300.0 K, rho = 10000.0 mol/m^3 (dense supercritical)
    let prep = eos.prepare(300.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(10000.0).unwrap();
    assert!((jet.pressure - 2.1049751492751230e+07).abs() < 2.1049751492751231e+04);
    let st = prep.state(10000.0).unwrap();
    assert!((st.ln_phi[0] - -2.7259096131486471e-01).abs() < 1e-5);
}

#[test]
fn test_saft_vrmie_binary_co2_c1() {
    let eos = SaftVrMie::new(&["CO2", "C1"]).expect("failed to load CO2,C1");
    assert_eq!(eos.num_components(), 2);
    assert_eq!(eos.get_kij(0, 1), 0.0);
    assert_eq!(eos.get_lij(0, 1), 0.0);

    let prep = eos.prepare(280.0, &[0.4, 0.6]).unwrap();
    let _terms = prep.helmholtz_terms(5000.0).unwrap();
    let jet = prep.pressure_and_derivatives(5000.0).unwrap();
    assert!((jet.pressure - 8.1241801122312928e+06).abs() < 1e-3 * 8.1241801122312928e+06);
    let st = prep.state(5000.0).unwrap();
    assert!((st.ln_phi[0] - -4.9836376670786747e-01).abs() < 1e-4);
    assert!((st.ln_phi[1] - -1.3314126363683471e-01).abs() < 1e-4);
}

#[test]
fn test_saft_vrmie_quantum_h2() {
    let eos = SaftVrMie::new(&["H2"]).expect("failed to load H2");
    let prep = eos.prepare(30.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(100.0).unwrap();
    assert!((jet.pressure - 2.4756981584705514e+04).abs() < 2.4756981584705514e+01);
    let st = prep.state(100.0).unwrap();
    assert!((st.ln_phi[0] - -7.4536733809171902e-03).abs() < 1e-5);

    let prep = eos.prepare(50.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(2000.0).unwrap();
    assert!((jet.pressure - 7.8672333617337479e+05).abs() < 7.8672333617337483e+02);
    let st = prep.state(2000.0).unwrap();
    assert!((st.ln_phi[0] - -5.4060538530472234e-02).abs() < 1e-5);

    let prep = eos.prepare(100.0, &[1.0]).unwrap();
    let jet = prep.pressure_and_derivatives(8000.0).unwrap();
    assert!((jet.pressure - 7.0100814832749311e+06).abs() < 7.0100814832749311e+03);
    let st = prep.state(8000.0).unwrap();
    assert!((st.ln_phi[0] - 3.2124502130409543e-02).abs() < 1e-5);
}

#[test]
fn exact_source_tvn() {
    use thermopack_rs::saft_vrmie::{HardSphereReference as Hs, MieTerms};
    let path = std::env::var_os("SAFTVRMIE_FIXTURE")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("tests/fixtures/saftvrmie_tvn.csv")
        });
    let csv = std::fs::read_to_string(path).unwrap();
    let numbers = |s: &str| {
        s.split(',')
            .map(|v| v.parse::<f64>().unwrap())
            .collect::<Vec<_>>()
    };
    let mut failures = Vec::new();
    for line in csv.lines().skip(1) {
        let fields: Vec<_> = line.split(';').collect();
        let comps: Vec<_> = fields[0].split(',').collect();
        let order = fields[2].parse::<i32>().unwrap();
        let mut model = if order < 0 {
            SaftVrMie::new_with_options(&comps, fields[1])
        } else {
            SaftVrMie::new_quantum(&comps, order as u8, Some(fields[1]))
        }
        .unwrap();
        model.set_hard_sphere_reference(match fields[3] {
            "1" => Hs::Lafitte,
            "2" => Hs::SingleComponent,
            "3" => Hs::Additive,
            "4" => Hs::NonAdditive,
            "5" => Hs::AdditiveExact,
            _ => panic!("unknown reference"),
        });
        let mask = fields[4].parse::<u8>().unwrap();
        model.set_terms(MieTerms {
            hard_sphere: mask & 1 != 0,
            first: mask & 2 != 0,
            second: mask & 4 != 0,
            third: mask & 8 != 0,
            chain: mask & 16 != 0,
        });
        use thermopack_rs::saft_vrmie::{PackingRule, QuantumVariant, SaftVrMieHelmholtz};
        let mut opts = model.options();
        match fields[11] {
            "jaen-kahn" => opts.quantum_variant = QuantumVariant::JaenKahn,
            "geometric" => opts.geometric_epsilon = true,
            "arithmetic-cross" => opts.exact_cross_potential = false,
            "linear" => opts.packing = PackingRule::Linear,
            "bmcsl" => opts.bmcsl_compressibility = true,
            "kolafa" => opts.kolafa_pure_reference = true,
            "pair-a3" => opts.pair_prefactor_a3 = true,
            "classical-a2" => opts.quantum_correct_a2 = false,
            "no-extra" => opts.extra_hard_sphere = false,
            "default" => {}
            _ => panic!("unknown options"),
        }
        model.set_options(opts).unwrap();
        let cutoff: f64 = fields[5].parse().unwrap();
        if cutoff > 0. {
            model.set_cutoff(Some((cutoff, fields[6] == "1"))).unwrap();
        }
        let t = fields[8].parse().unwrap();
        let v = fields[9].parse().unwrap();
        let n = numbers(fields[10]);
        let f = if fields[7] == "2" {
            let g = model.association_rdf_tvn(0, n.len() - 1, t, v, &n).unwrap();
            Ok(SaftVrMieHelmholtz {
                f: g.g,
                f_t: g.temperature,
                f_v: g.volume,
                f_n: g.moles,
                f_tt: g.temperature_second,
                f_tv: g.temperature_volume,
                f_tn: g.temperature_moles,
                f_vv: g.volume_second,
                f_vn: g.volume_moles,
                f_nn: g.moles_second,
                x_k: vec![],
            })
        } else if fields[7] == "1" {
            model.dispersion_tvn(t, v, &n)
        } else {
            model.residual_helmholtz_tvn(t, v, &n)
        }
        .unwrap();
        let mut values = vec![f.f, f.f_t, f.f_v];
        values.extend(f.f_n);
        values.extend([f.f_tt, f.f_tv]);
        values.extend(f.f_tn);
        values.push(f.f_vv);
        values.extend(f.f_vn);
        values.extend(f.f_nn);
        let mut expected = numbers(fields[12]);
        // The extra hard-sphere term in the Fortran VV routine includes
        // g/V^2 in place of g_V/V^2. Qualify using the Fortran V gradient.
        if n.len() > 1
            && matches!(fields[3], "3" | "5")
            && fields[7] == "0"
            && opts.extra_hard_sphere
        {
            expected[5 + 2 * n.len()] = fields[13].parse().unwrap();
        }
        assert_eq!(expected.len(), values.len());
        for (index, (value, reference)) in values.iter().zip(expected).enumerate() {
            if !value.is_finite() || (value - reference).abs() > 2e-11 + 3e-8 * reference.abs() {
                failures.push(format!(
                    "{:?} block {index}: {value:.8e} vs {reference:.8e}",
                    &fields[..12]
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
